CREATE TABLE review_preparation_absences (scan_id TEXT NOT NULL REFERENCES review_preparation_scans(scan_id) ON DELETE CASCADE, item_id TEXT NOT NULL, proposal_set_id TEXT NOT NULL REFERENCES proposal_sets(proposal_set_id), report_id TEXT NOT NULL REFERENCES metadata_reports(report_id), review_case_id TEXT NOT NULL REFERENCES review_cases(review_case_id), checkpoint INTEGER NOT NULL CHECK(checkpoint>0), kind TEXT NOT NULL CHECK(kind IN ('tombstoned','retired')), reason TEXT NOT NULL CHECK((kind='tombstoned' AND reason='absent') OR (kind='retired' AND reason='ineligible')), PRIMARY KEY(scan_id,item_id));
CREATE TABLE review_preparation_connection_conditions (connection_name TEXT PRIMARY KEY NOT NULL CHECK(typeof(connection_name)='text' AND length(CAST(connection_name AS BLOB)) BETWEEN 1 AND 64 AND connection_name NOT GLOB '*[^a-z0-9_-]*' AND substr(connection_name,1,1) GLOB '[a-z]'), code TEXT NOT NULL CHECK(code IN ('tls','authentication','authorization','unavailable')), state TEXT NOT NULL CHECK(state IN ('paused','checking','recovered')), epoch INTEGER NOT NULL CHECK(epoch>=1), affected INTEGER NOT NULL CHECK(affected>=0), updated_at INTEGER NOT NULL CHECK(updated_at>=0));
CREATE TABLE review_preparation_control (singleton INTEGER PRIMARY KEY NOT NULL CHECK(singleton=1), paused INTEGER NOT NULL CHECK(paused IN (0,1)), claim_sequence INTEGER NOT NULL CHECK(claim_sequence>=0), first_boot_acknowledged INTEGER NOT NULL CHECK(first_boot_acknowledged IN (0,1)), last_library TEXT CHECK(last_library IS NULL OR (typeof(last_library)='text' AND length(CAST(last_library AS BLOB)) BETWEEN 1 AND 64 AND last_library NOT GLOB '*[^a-z0-9_-]*' AND substr(last_library,1,1) GLOB '[a-z]')), circuit_failures INTEGER NOT NULL CHECK(circuit_failures BETWEEN 0 AND 3), circuit_open_until INTEGER NOT NULL CHECK(circuit_open_until>=0), updated_at INTEGER NOT NULL CHECK(updated_at>=0));
