CREATE TRIGGER description_advice_candidates_no_update BEFORE UPDATE ON description_advice_candidates BEGIN SELECT RAISE(ABORT, 'description history is immutable'); END;
CREATE TRIGGER description_advice_candidates_no_delete BEFORE DELETE ON description_advice_candidates BEGIN SELECT RAISE(ABORT, 'description history is immutable'); END;
CREATE TRIGGER description_decisions_no_update BEFORE UPDATE ON description_decisions BEGIN SELECT RAISE(ABORT, 'description history is immutable'); END;
CREATE TRIGGER description_decisions_no_delete BEFORE DELETE ON description_decisions BEGIN SELECT RAISE(ABORT, 'description history is immutable'); END;
CREATE INDEX metadata_report_cover_references_artifact_id ON metadata_report_cover_references(artifact_id) WHERE artifact_id IS NOT NULL;
CREATE INDEX metadata_report_cover_references_preview_digest ON metadata_report_cover_references(preview_digest) WHERE preview_digest IS NOT NULL;
CREATE TRIGGER review_cases_project_field_facts AFTER INSERT ON review_cases BEGIN INSERT INTO review_case_field_facts(review_case_id,destination,unresolved_choice,manual_bibliographic_attention,has_owner_decision_actions) SELECT NEW.review_case_id,json_extract(result.value,'$.destination'),CASE WHEN json_extract(result.value,'$.outcome')='unresolved_choice' THEN 1 ELSE 0 END,CASE WHEN json_extract(result.value,'$.destination') IN ('title','subtitle','series') AND EXISTS (SELECT 1 FROM json_each(NEW.document,'$.results') sibling WHERE json_extract(sibling.value,'$.destination') IN ('title','subtitle','series') AND json_array_length(json_extract(sibling.value,'$.reasons'))=1 AND json_extract(sibling.value,'$.reasons[0]')='no_safe_bibliographic_combination') THEN 1 ELSE 0 END,CASE WHEN (json_extract(result.value,'$.outcome') IN ('propose_change','acceptable_choice','unresolved_choice') OR (json_extract(result.value,'$.destination') IN ('title','subtitle','series') AND EXISTS (SELECT 1 FROM json_each(NEW.document,'$.results') sibling WHERE json_extract(sibling.value,'$.destination') IN ('title','subtitle','series') AND json_array_length(json_extract(sibling.value,'$.reasons'))=1 AND json_extract(sibling.value,'$.reasons[0]')='no_safe_bibliographic_combination'))) AND EXISTS (SELECT 1 FROM json_each(result.value,'$.alternatives') alternative WHERE json_extract(alternative.value,'$.assessment')<>'preserves_target') THEN 1 ELSE 0 END FROM json_each(NEW.document,'$.results') result; END;
CREATE INDEX review_preparation_presentation_active ON review_preparation_presentation(run_id,current_work_state,enrollment_ordinal,ordinal,work_id) WHERE row_kind='work';
CREATE UNIQUE INDEX review_preparation_presentation_recent ON review_preparation_presentation(run_id,completion_sequence DESC) WHERE row_kind='work' AND work_outcome IS NOT NULL;
CREATE INDEX review_preparation_presentation_completion_integrity ON review_preparation_presentation(run_id,completion_sequence) WHERE row_kind='work' AND completion_sequence IS NOT NULL;
CREATE INDEX review_preparation_presentation_run ON review_preparation_presentation(run_id,row_kind,ordinal);
CREATE INDEX review_preparation_presentation_throughput ON review_preparation_presentation(run_id,updated_at) WHERE row_kind='work' AND work_outcome IS NOT NULL;
CREATE INDEX review_preparation_work_aged_claim ON review_preparation_work(state,library_name,ordinal);
CREATE INDEX review_preparation_work_due_promotion ON review_preparation_work(state,retry_not_before);
CREATE INDEX review_preparation_work_recent_claim ON review_preparation_work(state,library_name,updated_at DESC,ordinal);
CREATE INDEX review_preparation_work_lineage_history ON review_preparation_work(connection_name,library_name,item_id,updated_at DESC,work_id DESC);
CREATE INDEX shadow_decision_outcomes_case_history ON shadow_decision_outcomes(review_case_id,evaluated_at DESC,outcome_set_id DESC);
CREATE INDEX shadow_outcome_field_facts_case ON shadow_outcome_field_facts(review_case_id,destination,disposition);
CREATE TRIGGER shadow_outcomes_project_field_facts AFTER INSERT ON shadow_decision_outcomes BEGIN INSERT INTO shadow_outcome_field_facts(outcome_set_id,review_case_id,destination,disposition,automatic_destination,policy_category) SELECT NEW.outcome_set_id,NEW.review_case_id,json_extract(outcome.value,'$.destination'),json_extract(outcome.value,'$.disposition'),CASE WHEN json_extract(outcome.value,'$.policy_destination')='automatic' THEN 1 ELSE 0 END,json_extract(outcome.value,'$.policy_category') FROM json_each(NEW.document,'$.outcomes') outcome; END;
